import {
  useCallback,
  useEffect,
  useMemo,
  useRef,
  useState,
  type PointerEvent as ReactPointerEvent,
} from "react";
import "./prism-carousel.css";

/**
 * Prism Carousel —— 会「过色」的封面流。
 *
 * 借自 React Bits Pro 的同名组件（a coverflow that sweeps color into each
 * new image）的形态：卡片排成一圈弧，正面对着你的那张最亮最大；左右两张
 * 向后转、退远、压暗。翻到新的一张时，一道棱镜光从那张卡的左边扫到右边，
 * 颜色是这张卡自己的色相 —— 换卡的动作因此有了「刷」的一下。
 *
 * 拖动、滚轮、左右方向键都能翻；点侧边的卡片把它转到正面，点正面的卡片
 * 打开（onSelect）。prefers-reduced-motion 时不做扫光，直接落位。
 */

export interface PrismCarouselItem {
  id: string;
  title: string;
  /** 卡片正文，两三行。 */
  body?: string;
  /** 卡片脚下的小字：来源、日期、页签之类。 */
  meta?: string;
  /** 主题色相 0..360；不传就按 id 算一个稳定的。 */
  hue?: number;
}

interface PrismCarouselProps {
  items: PrismCarouselItem[];
  activeIndex?: number;
  onActiveChange?: (index: number) => void;
  onSelect?: (item: PrismCarouselItem) => void;
  className?: string;
  emptyLabel?: string;
}

const STEP = 208;
const VISIBLE_SPAN = 2.6;

function hashHue(id: string) {
  let hash = 5381;
  for (let index = 0; index < id.length; index += 1) {
    hash = (hash * 33) ^ id.charCodeAt(index);
  }
  return (hash >>> 0) % 360;
}

export function PrismCarousel({
  items,
  activeIndex,
  onActiveChange,
  onSelect,
  className = "",
  emptyLabel = "还没有卡片。",
}: PrismCarouselProps) {
  const [innerIndex, setInnerIndex] = useState(0);
  const [sweep, setSweep] = useState<{ index: number; key: number }>({
    index: 0,
    key: 0,
  });
  const [reduced, setReduced] = useState(false);
  const viewportRef = useRef<HTMLDivElement>(null);
  const dragRef = useRef<{ x: number; startIndex: number; moved: boolean } | null>(null);
  const positionRef = useRef(0);
  const positionalAccum = useRef(0);
  const [position, setPosition] = useState(0);
  const rafRef = useRef(0);

  const index = Math.max(0, Math.min(items.length - 1, activeIndex ?? innerIndex));

  const hues = useMemo(
    () => new Map(items.map((item) => [item.id, item.hue ?? hashHue(item.id)])),
    [items],
  );

  useEffect(() => {
    const query = window.matchMedia("(prefers-reduced-motion: reduce)");
    const apply = () => setReduced(query.matches);
    apply();
    query.addEventListener("change", apply);
    return () => query.removeEventListener("change", apply);
  }, []);

  const commitIndex = useCallback(
    (next: number) => {
      const clamped = Math.max(0, Math.min(items.length - 1, next));
      if (activeIndex === undefined) setInnerIndex(clamped);
      setSweep((current) => ({ index: clamped, key: current.key + 1 }));
      onActiveChange?.(clamped);
    },
    [activeIndex, items.length, onActiveChange],
  );

  // position 追着 index 走，翻页就有了滑行而不是瞬移。
  useEffect(() => {
    const animate = () => {
      const delta = index - positionRef.current;
      if (Math.abs(delta) < 0.0015) {
        positionRef.current = index;
        setPosition(index);
        rafRef.current = 0;
        return;
      }
      positionRef.current += delta * (reduced ? 1 : 0.16);
      setPosition(positionRef.current);
      rafRef.current = window.requestAnimationFrame(animate);
    };
    if (!rafRef.current) rafRef.current = window.requestAnimationFrame(animate);
    return () => {
      if (rafRef.current) {
        window.cancelAnimationFrame(rafRef.current);
        rafRef.current = 0;
      }
    };
  }, [index, reduced]);

  const onWheel = useCallback(
    (event: React.WheelEvent<HTMLDivElement>) => {
      event.stopPropagation();
      const delta = Math.abs(event.deltaX) > Math.abs(event.deltaY)
        ? event.deltaX
        : event.deltaY;
      if (Math.abs(delta) < 4) return;
      positionalAccum.current += delta;
      if (Math.abs(positionalAccum.current) > 90) {
        commitIndex(index + (positionalAccum.current > 0 ? 1 : -1));
        positionalAccum.current = 0;
      }
    },
    [commitIndex, index],
  );

  const onPointerDown = useCallback(
    (event: ReactPointerEvent<HTMLDivElement>) => {
      dragRef.current = { x: event.clientX, startIndex: index, moved: false };
    },
    [index],
  );

  const onPointerMove = useCallback(
    (event: ReactPointerEvent<HTMLDivElement>) => {
      const drag = dragRef.current;
      if (!drag) return;
      const delta = event.clientX - drag.x;
      if (Math.abs(delta) > 46) {
        // 真的拖起来了才把指针接过来：在 pointerdown 就 capture 的话，
        // pointerup 会被重定到根节点，浏览器算出来的 click 目标也变成根节点 ——
        // 正中间那张卡就点不动了（点一下本该进编辑）。只点不拖时不 capture，
        // click 照旧落在卡片自己身上。
        if (!event.currentTarget.hasPointerCapture(event.pointerId)) {
          event.currentTarget.setPointerCapture(event.pointerId);
        }
        drag.moved = true;
        commitIndex(drag.startIndex + (delta < 0 ? 1 : -1));
        drag.x = event.clientX;
        drag.startIndex = index;
      }
    },
    [commitIndex, index],
  );

  const onPointerUp = useCallback((event: ReactPointerEvent<HTMLDivElement>) => {
    dragRef.current = null;
    if (event.currentTarget.hasPointerCapture(event.pointerId)) {
      event.currentTarget.releasePointerCapture(event.pointerId);
    }
  }, []);

  const onKeyDown = useCallback(
    (event: React.KeyboardEvent<HTMLDivElement>) => {
      if (event.key === "ArrowRight") {
        event.preventDefault();
        commitIndex(index + 1);
      } else if (event.key === "ArrowLeft") {
        event.preventDefault();
        commitIndex(index - 1);
      }
    },
    [commitIndex, index],
  );

  if (!items.length) {
    return (
      <div className={`prism-carousel prism-carousel--empty ${className}`.trim()}>
        <p>{emptyLabel}</p>
      </div>
    );
  }

  return (
    <div
      ref={viewportRef}
      className={`prism-carousel ${className}`.trim()}
      role="listbox"
      aria-label="知识卡片"
      tabIndex={0}
      onWheel={onWheel}
      onPointerDown={onPointerDown}
      onPointerMove={onPointerMove}
      onPointerUp={onPointerUp}
      onPointerCancel={onPointerUp}
      onKeyDown={onKeyDown}
    >
      <div className="prism-carousel__stage">
        {items.map((item, itemIndex) => {
          const offset = itemIndex - position;
          const distance = Math.abs(offset);
          const hue = hues.get(item.id) ?? 210;
          const isActive = distance < 0.5;
          return (
            <article
              key={item.id}
              className="prism-carousel__card"
              data-active={isActive ? "" : undefined}
              style={{
                ["--card-hue" as string]: String(hue),
                transform: `translate3d(${(offset * STEP).toFixed(1)}px, 0, ${(-distance * 132).toFixed(0)}px) rotateY(${(-offset * 32).toFixed(2)}deg) scale(${(1 - distance * 0.045).toFixed(3)})`,
                opacity: distance > VISIBLE_SPAN ? 0 : 1 - distance * 0.24,
                zIndex: 100 - Math.round(distance * 10),
                pointerEvents: distance > VISIBLE_SPAN ? "none" : "auto",
              }}
              aria-hidden={isActive ? undefined : true}
              onClick={() => {
                if (dragRef.current?.moved) return;
                if (!isActive) {
                  commitIndex(itemIndex);
                  return;
                }
                onSelect?.(item);
              }}
            >
              {/* 翻到这张卡时挂上带 key 的扫光：key 一变就重挂，CSS 动画
                  跟着重新开始 —— 只改属性值是不会重启动画的。 */}
              {sweep.index === itemIndex && !reduced ? (
                <span
                  key={sweep.key}
                  className="prism-carousel__sweep"
                  aria-hidden="true"
                />
              ) : null}
              <span className="prism-carousel__glyph" aria-hidden="true">
                {item.title.slice(0, 1).toUpperCase()}
              </span>
              <strong>{item.title}</strong>
              {item.body ? <p>{item.body}</p> : null}
              {item.meta ? <small>{item.meta}</small> : null}
              <span className="prism-carousel__edge" aria-hidden="true" />
            </article>
          );
        })}
      </div>
      <div className="prism-carousel__rail" aria-hidden="true">
        {items.map((item, itemIndex) => (
          <i key={item.id} data-active={itemIndex === index ? "" : undefined} />
        ))}
      </div>
    </div>
  );
}

export default PrismCarousel;
