export interface BookDefinition {
  id: BookId;
  /** Title on the spine, shown in the hover label and the panel header. */
  title: string;
  zhTitle: string;
  author: string;
  /** Spine colour, one of the four accent colours from the brief. */
  spine: string;
  /** Warm paper tint used by the open pages. */
  pageTint: string;
  /** Shelf grid cell: [column 0-3, row 0-4 from the floor up]. */
  slot: [number, number];
  /** Book cover width in metres (spine to fore-edge). */
  coverWidth: number;
  /** Book height in metres. */
  height: number;
  /** Spine thickness in metres. */
  thickness: number;
  /** Slight lean, in radians, so the shelf does not look machine-made. */
  lean: number;
  /** Users can paste their own English into the blank book. */
  editable: boolean;
  /** Public-domain or original sample text shown on the left page. */
  source: string;
  /** Curated Chinese translation shown on the right page. */
  translation: string;
}

