export function fillerColor(index: number): string {
  return FILLER_PALETTE[index % FILLER_PALETTE.length] ?? FILLER_PALETTE[0]!;
}

export function fillerTitle(index: number): string {
  return FILLER_TITLES[index % FILLER_TITLES.length] ?? "Notes";
}

